import React, { useState, useEffect, useRef } from "react";

/* ----------------------------------------------------------------------
   خلفية الموقع الجديدة (سيارتا BMW وAudi تحت الجسر، أنوارهما مضاءة أصلاً
   في الصورة نفسها) — تُستخدم الآن كخلفية وحيدة للموقع بالكامل (وأيضًا
   للوحة التحكم)، بدل الصورة السابقة، وبدل أي سكشن منفصل يظهر أثناء
   التمرير. الصورة الأصلية تُستخدم كما هي حرفيًا بدون أي توليد أو تعديل
   على السيارات، الأضواء، أو الـHazard — فقط طبقات توهج شفافة فوقها في
   نفس مكان الأضواء الأصلية بالضبط. ---------------------------------------- */
const HEADLIGHTS_PHOTO_IMG = "data:image/jpeg;base64,";

// منحنى الإشعال التدريجي: عتمة كاملة عند 0%، بصيص عند 20%، ثم اكتمال
// الإضاءة تدريجيًا حتى 100% — لا تضيء الصورة دفعة واحدة أبدًا.
const HEADLIGHT_CURVE = [
  [0, 0],
  [0.2, 0.08],
  [0.4, 0.38],
  [0.6, 0.7],
  [0.8, 0.9],
  [1, 1],
];
function curveValue(points, p) {
  if (p <= points[0][0]) return points[0][1];
  for (let i = 1; i < points.length; i++) {
    const [x0, y0] = points[i - 1];
    const [x1, y1] = points[i];
    if (p <= x1) {
      const t = (p - x0) / (x1 - x0 || 1);
      return y0 + (y1 - y0) * t;
    }
  }
  return points[points.length - 1][1];
}

// إحداثيات مصابيح الأمامية الأربعة (% من أبعاد الصورة 1376×768) — قيست
// يدويًا من نفس الصورة الجديدة: BMW يسار/يمين ثم Audi يسار/يمين. لم يتم
// تغيير مكان الأضواء ولا ألوانها إطلاقًا، فقط طُبِّق التوهج فوق مكانها
// الأصلي بالضبط كما هي مضاءة في الصورة.
const HEADLIGHT_SPOTS = [
  { key: "bmw-l", x: 15.3, y: 55.4, rx: 6.2, ry: 8 },
  { key: "bmw-r", x: 42.2, y: 55.4, rx: 6.6, ry: 8 },
  { key: "audi-l", x: 61.8, y: 52.9, rx: 6.4, ry: 5.6 },
  { key: "audi-r", x: 88.7, y: 54, rx: 6.4, ry: 5.6 },
];
function GlowLayer({ id }) {
  return (
    <>
      <img src={HEADLIGHTS_PHOTO_IMG} alt="" className="cl-photo" loading="eager" decoding="async" />
      <div className="cl-haze" />
      <div className="cl-ground-reflection" />
      {/* بدل إضافة أشكال ضوء بيضاء/كهرمانية مصطنعة فوق الصورة، نغطي كل
          مصباح بـ"رقعة إطفاء" داكنة بنفس شكل ومكان الضوء الحقيقي في
          الصورة، ثم نُخفي هذه الرقعة تدريجيًا — فيظهر الضوء الحقيقي الذي
          كان مصوَّرًا مضاءً أصلاً، فيبدو الإشعال حقيقيًا 100% لأنه نفس
          بكسلات الصورة الأصلية وليس شكلاً مولَّدًا. */}
      {HEADLIGHT_SPOTS.map((s) => (
        <span
          key={id + "-h-" + s.key}
          className="cl-headlight-off"
          style={{ left: `${s.x}%`, top: `${s.y}%`, width: `${s.rx * 2}%`, height: `${s.ry * 2}%` }}
        />
      ))}
    </>
  );
}

/* ---------------- خلفية الموقع الطبيعية (زبون + لوحة تحكم) ----------------
   بدل سكشن منفصل يظهر أثناء التمرير وكأنه جزء من محتوى الصفحة: هذه خلفية
   ثابتة (fixed) خلف كامل الموقع طوال وقت التصفح، تُشعل نفسها تلقائيًا مرة
   واحدة فور فتح الصفحة (مرتبطة بالوقت فقط، بدون أي علاقة بالـscroll)، ثم
   يبقى الـHazard وامضًا إلى الأبد — تمامًا كما طُلب. */
function AmbientLights({ rootClassName, idPrefix, trigger }) {
  const rootRef = useRef(null);

  // وضع "بالوقت" (لوحة التحكم فقط): إشعال تلقائي مرة واحدة فور فتح الصفحة،
  // بدون أي علاقة بالسكرول. لا يوجد أي وميض بعد اكتمال الإشعال — تبقى
  // الأضواء مضاءة بثبات كما هي في الصورة الأصلية.
  useEffect(() => {
    if (trigger !== "time") return;
    const el = rootRef.current;
    if (!el) return;
    const DURATION = 2600;
    const start =
      typeof performance !== "undefined" && performance.now ? performance.now() : Date.now();
    let raf = null;

    const tick = (now) => {
      const elapsed = (now || Date.now()) - start;
      const p = Math.max(0, Math.min(1, elapsed / DURATION));
      const glow = curveValue(HEADLIGHT_CURVE, p);
      const darkness = 1 - glow;

      el.style.setProperty("--lp", p.toFixed(4));
      el.style.setProperty("--glow-op", glow.toFixed(4));
      el.style.setProperty("--dark-op", darkness.toFixed(4));

      if (p < 1) raf = window.requestAnimationFrame(tick);
    };

    raf = window.requestAnimationFrame(tick);
    return () => {
      if (raf) window.cancelAnimationFrame(raf);
    };
  }, [trigger]);

  // وضع "بالسكرول" (موقع الزبون): كلما نزل الزائر في الصفحة زاد توهج
  // الأضواء تدريجيًا حتى تكتمل الإضاءة، بدون أي وميض بعد ذلك.
  useEffect(() => {
    if (trigger !== "scroll") return;
    const el = rootRef.current;
    if (!el) return;
    let raf = null;
    let ticking = false;

    const apply = () => {
      ticking = false;
      const threshold = Math.max(320, window.innerHeight * 0.85);
      // Now that this background sits fixed behind the whole site (not a
      // section scrolled into view), scrollY===0 on first load used to mean
      // p=0 → darkness=1 → the headlight patches rendered fully black, i.e.
      // the "black dots" seen on the loading screen before any scrolling
      // happened. A small floor keeps them always at least partly lit, and
      // scrolling still brightens them further from there.
      const p = Math.max(0.35, Math.min(1, window.scrollY / threshold));
      const glow = curveValue(HEADLIGHT_CURVE, p);
      const darkness = 1 - glow;

      el.style.setProperty("--lp", p.toFixed(4));
      el.style.setProperty("--glow-op", glow.toFixed(4));
      el.style.setProperty("--dark-op", darkness.toFixed(4));
    };

    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      raf = window.requestAnimationFrame(apply);
    };

    apply();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) window.cancelAnimationFrame(raf);
    };
  }, [trigger]);

  return (
    <div ref={rootRef} className={rootClassName} aria-hidden="true">
      <div className="cl-media">
        <GlowLayer id={idPrefix} />
      </div>
    </div>
  );
}

// خلفية موقع الزبون — ثابتة خلف كل الصفحة طوال التصفح (وليست سكشن منفصل
// يظهر أثناء التمرير كما كان سابقًا)، لكن إشعالها هنا مرتبط بالسكرول:
// كلما نزل الزائر تزداد الإضاءة تدريجيًا، وبعد أول شاشة تمرير يبقى
// الـHazard وامضًا للأبد.
function SiteAmbientLights() {
  return <AmbientLights rootClassName="site-ambient" idPrefix="site" trigger="scroll" />;
}

// نفس الخلفية بالضبط للوحة التحكم — لكن إشعالها تلقائي بالوقت فور الدخول،
// بدون أي علاقة بالسكرول.
function DashboardAmbientLights() {
  return <AmbientLights rootClassName="dashboard-ambient" idPrefix="dash" trigger="time" />;
}

export { HEADLIGHTS_PHOTO_IMG, SiteAmbientLights, DashboardAmbientLights };
